pkg/controller/tainteviction/timed_workers.go L103-117 @ ef9e14db79
OBSERVATION: This function wraps the worker function to run. If the worker function succeeds (err == nil), it assigns nil to q.workers[key] deliberately to keep the key in the map to avoid duplicate work. The bug description explains that if CancelWork is called concurrently and obtains the lock first, it will delete q.workers[key]. But if getWrappedWorkerFunc runs and sets q.workers[key]=nil later, the key stays in the map with a nil value, leading subsequent AddWork calls to skip adding new work.
func (q *TimedWorkerQueue) getWrappedWorkerFunc(key string) func(ctx context.Context, fireAt time.Time, args *WorkArgs) error {
	return func(ctx context.Context, fireAt time.Time, args *WorkArgs) error {
		err := q.workFunc(ctx, fireAt, args)
		q.Lock()
		defer q.Unlock()
		if err == nil {
			// To avoid duplicated calls we keep the key in the queue, to prevent
			// subsequent additions.
			q.workers[key] = nil
		} else {
			delete(q.workers, key)
		}
		return err
	}
}

pkg/controller/tainteviction/timed_workers.go L136-150 @ ef9e14db79
OBSERVATION: CancelWork locks the queue and deletes the worker from q.workers map. However, if getWrappedWorkerFunc is concurrently releasing the lock and sets q.workers[key] = nil right after CancelWork deletes it, the key will reappear in q.workers map with nil value, causing AddWork to skip adding the new work in the future.
func (q *TimedWorkerQueue) CancelWork(logger klog.Logger, key string) bool {
	q.Lock()
	defer q.Unlock()
	worker, found := q.workers[key]
	result := false
	if found {
		logger.V(4).Info("Cancelling TimedWorkerQueue item", "item", key, "time", time.Now())
		if worker != nil {
			result = true
			worker.Cancel()
		}
		delete(q.workers, key)
	}
	return result
}

