staging/src/k8s.io/apiserver/pkg/cel/library/cidr.go L221-234 @ 4205f04ce3
OBSERVATION: The bug is located in the cidrContainsCIDR function which implements the containsCIDR CEL check. The code tries to compare masking of the CIDR prefixes using netip.Prefix.Masked() and netip.PrefixFrom but incorrectly constructs the masked prefix for the argument 'containsCIDR'. The second argument to netip.PrefixFrom uses cidr.Prefix.Bits() instead of containsCIDR.Prefix.Bits(), causing an incorrect mask length on the second prefix Addr which breaks the containment logic when containing and contained CIDRs have different prefix lengths and addresses. This matches the bug described in the ticket where the masking logic doesn't behave as intended for different CIDRs.
func cidrContainsCIDR(arg ref.Val, other ref.Val) ref.Val {
	cidr, ok := arg.(apiservercel.CIDR)
	if !ok {
		return types.MaybeNoSuchOverloadErr(arg)
	}

	containsCIDR, ok := other.(apiservercel.CIDR)
	if !ok {
		return types.MaybeNoSuchOverloadErr(other)
	}

	equalMasked := cidr.Prefix.Masked() == netip.PrefixFrom(containsCIDR.Prefix.Addr(), cidr.Prefix.Bits())
	return types.Bool(equalMasked && cidr.Prefix.Bits() <= containsCIDR.Prefix.Bits())
}

