OBSERVATION: This function creates a conntrack filter that matches connections with a specific original destination IP and reply source IP, by parsing IPs and filling the structure. The log message "Adding conntrack filter for cleanup" is triggered here for every filter added, which results in thousands of such logs on UDP pod updates, correlating with the memory spike.
func filterForNAT(origin, dest string, protocol v1.Protocol) *conntrackFilter {
	klog.V(4).InfoS("Adding conntrack filter for cleanup", "org-dst", origin, "reply-src", dest, "protocol", protocol)
	return &conntrackFilter{
		protocol: protocolMap[protocol],
		original: &connectionTuple{
			dstIP: netutils.ParseIPSloppy(origin),
		},
		reply: &connectionTuple{
			srcIP: netutils.ParseIPSloppy(dest),
		},
	}
}

