// Conflicts returns true if two SELinux labels conflict.
func (c *ControllerSELinuxTranslator) Conflicts(labelA, labelB string) bool {
	// No conflict if labels are equal
	if labelA == labelB {
		return false
	}

	// Empty label means mounting context can be anything. No conflict.
	if labelA == "" || labelB == "" {
		return false
	}

	// Compare the parts of the labels
	partsA := strings.Split(labelA, ":")
	partsB := strings.Split(labelB, ":")

	if len(partsA) != len(partsB) {
		return true
	}

	// Only compare the last part (level) if the prefixes are equal
	if !equalSlice(partsA[:len(partsA)-1], partsB[:len(partsB)-1]) {
		return true
	}

	// Finally compare the last parts
	return partsA[len(partsA)-1] != partsB[len(partsB)-1]
}

