// resourceVersionLess compares two resource versions to figure out which is older.
func resourceVersionLess(lhs, rhs string) bool {
	lhsv, err := strconv.ParseUint(lhs, 10, 64)
	if err != nil {
		klog.ErrorS(err, "Invalid resource version", "value", lhs)
		return false
	}
	rhsv, err := strconv.ParseUint(rhs, 10, 64)
	if err != nil {
		klog.ErrorS(err, "Invalid resource version", "value", rhs)
		return false
	}
	return lhsv < rhsv
}

// resourceVersionNewer checks if lhs is newer than rhs.
func resourceVersionNewer(lhs, rhs string) bool {
	return resourceVersionLess(rhs, lhs)
}

